WITH lines AS (SELECT id, service, host, log_ts, level, key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS key, v), filtered AS (SELECT *, DATEDIFF(CURRENT_DATE(), log_ts) AS days_since_log_ts, COALESCE(key, 'OTHER') AS key_filled FROM lines WHERE log_ts < '2024-07-19'), cleaned AS (SELECT id, host, log_ts, level, v, days_since_log_ts, key_filled, TO_DATE(log_ts) AS log_ts_date FROM filtered WHERE log_ts >= TO_TIMESTAMP('2025-06-01 15:00:00') AND key <> 'trace') SELECT id, host, log_ts, level, v, days_since_log_ts, key_filled, log_ts_date, MAX(days_since_log_ts) OVER (PARTITION BY host, level ORDER BY CAST(log_ts AS BIGINT) ASC RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS days_since_log_ts_max_15m, DENSE_RANK() OVER (PARTITION BY host ORDER BY days_since_log_ts DESC NULLS LAST) AS days_since_log_ts_dense_rank FROM cleaned
